export interface components {
    schemas: {
        SalesPrompt: {
            id: string;
            title: string;
            description: string;
            prompt: string;
            defaultPrompt: string;
            version: string;
            customized: boolean;
        };
        VideoDownloadRequest: {
            directory: string;
            directoryToken: string;
            /**
             * @default 100
             * @enum {integer}
             */
            concurrency: 0 | 100;
            items: {
                /** @description 单个安全视频文件名；同名已存在时拒绝覆盖 */
                filename: string;
                /** @description 由后端视频代理安全策略校验的远程 URL */
                url: string;
            }[];
        };
        VideoDownloadSnapshot: {
            jobId: string;
            directory: string;
            running: boolean;
            items: {
                filename: string;
                url: string;
                /** @enum {string} */
                status: "pending" | "running" | "success" | "failed";
                error?: string;
            }[];
        };
        CategoryLearningNote: {
            id: string;
            /** @enum {string} */
            kind: "prefer" | "avoid";
            content: string;
            createdAt: string;
        };
        CategoryLearningEntry: {
            groupId: string;
            title: string;
            /** @enum {string} */
            state: "pending" | "learned" | "rejected" | "holdout";
            reason: string;
            rules: string[];
            conditions: string[];
            avoid: string[];
            model: string;
            createdAt: string;
        };
        CategoryLearningMemory: {
            entries: components["schemas"]["CategoryLearningEntry"][];
            notes: components["schemas"]["CategoryLearningNote"][];
            learned: number;
            pending: number;
            rejected: number;
            holdout: number;
            fingerprint: string;
        };
        /** @description 文本及图片理解模型路由；模型级显式协议优先，auto按真实上游模型识别Gemini或Anthropic原生协议，不改变渠道地址与密钥，也不自动回退协议。 */
        TextModelRoute: {
            model?: string;
            /**
             * @default auto
             * @enum {string}
             */
            textProtocol: "auto" | "openai" | "gemini" | "anthropic";
            customBaseUrl?: string;
            customApiKey?: string;
        };
        AssistantTurnStartRequest: components["schemas"]["TextModelRoute"] & ({
            messages: ({
                /** @enum {string} */
                role: "user" | "assistant" | "system";
                content: string;
            } & {
                [key: string]: unknown;
            })[];
            /**
             * @default medium
             * @enum {string}
             */
            reasoningEffort: "auto" | "low" | "medium" | "high" | "xhigh" | "max";
        } & {
            [key: string]: unknown;
        });
        CollectVariantMetadata: {
            /** @enum {integer} */
            version: 1;
            variants: {
                id: string;
                label: string;
                color?: string;
                skuIds: string[];
                imageUrls: string[];
            }[];
            requestedSkuId?: string;
            selectedVariantId?: string;
        };
        SalesSummaryImage: {
            index: number;
            url: string;
        };
        /** @description 去重后最多16张原图、合计20MiB；核对文字合计最多60000字。 */
        SalesSummaryRequest: {
            productName: string;
            brand: string;
            facts: string;
            referenceImages: components["schemas"]["SalesSummaryImage"][];
            textImages: (components["schemas"]["SalesSummaryImage"] & {
                text: string;
            })[];
            model: string;
            /** @enum {string} */
            textProtocol?: "auto" | "openai" | "gemini" | "anthropic";
            customBaseUrl?: string;
            customApiKey?: string;
            /** @enum {string} */
            apiFormat?: "openai-responses";
            allowInsecureHttp?: boolean;
        };
        SalesSummaryResult: {
            /**
             * @description 来自商品资料的关键使用与养护限制；补足已收录标签中的明确限制。
             * @default []
             */
            cautions: string[];
            summary: string;
            points: {
                feature: string;
                benefit: string;
                expression: string;
                sources: string[];
            }[];
            copy: string;
            /**
             * @description 成稿生成时参考的买点，使用 points 中从 1 开始的编号；旧结果默认空数组。
             * @default []
             */
            copyPointIndexes: number[];
            conflicts: string[];
            questions: string[];
        };
        SalesOCRRequest: {
            imageUrl: string;
            /** @default false */
            force: boolean;
        };
        SalesOCRResult: {
            engine: string;
            width: number;
            height: number;
            text: string;
            cached: boolean;
            lines: {
                box: number[][];
                text: string;
                confidence: number;
            }[];
        };
    };
    responses: {
        /** @description 请求、授权或运行环境不允许此操作；error 含可展示的原因 */
        VideoDownloadError: {
            headers: {
                [name: string]: unknown;
            };
            content: {
                "application/json": {
                    /** @enum {boolean} */
                    success: false;
                    error: string;
                };
            };
        };
    };
    parameters: never;
    requestBodies: never;
    headers: never;
    pathItems: never;
}
